function cleanWikiHtml(raw){
 const parsed=new DOMParser().parseFromString(raw,"text/html");
 const allowed=new Set(["P","H1","H2","H3","H4","UL","OL","LI","TABLE","TBODY","THEAD","TR","TD","TH","BLOCKQUOTE","FIGURE","FIGCAPTION","SPAN","DIV","DL","DT","DD","SMALL","SUP","SUB","B","STRONG","I","EM","A","IMG","BR","HR","CODE","PRE"]);
 function copy(node){
  if(node.nodeType===Node.TEXT_NODE)return document.createTextNode(node.textContent||"");
  if(node.nodeType!==Node.ELEMENT_NODE)return document.createDocumentFragment();
  const tag=node.tagName;
  if(["SCRIPT","STYLE","IFRAME","FORM","INPUT","BUTTON","VIDEO","AUDIO","SVG","MATH","NOSCRIPT"].includes(tag))return document.createDocumentFragment();
  if(!allowed.has(tag)){const frag=document.createDocumentFragment();[...node.childNodes].forEach(child=>frag.append(copy(child)));return frag}
  const el=document.createElement(tag.toLowerCase());
  if(tag==="A"){
   const href=node.getAttribute("href")||"";
   if((href.startsWith("/wiki/")||href.startsWith("./"))&&!href.includes(":")){const wikiPath=href.startsWith("./")?"/wiki/"+href.slice(2):href;el.dataset.wikiHref=wikiPath;el.href="#"}
   else if(/^https:\/\//i.test(href)){el.href=href;el.target="_blank";el.rel="noopener noreferrer"}
   else return document.createDocumentFragment();
  }
  if(tag==="IMG"){
   const src=node.getAttribute("src")||node.getAttribute("resource")||"";
   if(!src.startsWith("https://upload.wikimedia.org/"))return el;
   el.src=src;el.alt=(node.getAttribute("alt")||"").slice(0,200);el.loading="lazy";el.referrerPolicy="no-referrer";
  }
  [...node.childNodes].forEach(child=>el.append(copy(child)));return el;
 }
 const root=document.createElement("div");[...parsed.body.childNodes].forEach(node=>root.append(copy(node)));
 root.querySelectorAll(".mw-editsection,.mw-references-wrap,.navbox,.metadata,.mw-empty-elt").forEach(n=>n.remove());return root.innerHTML;
}
