function setPage(t,h){$("#view-name").textContent=t;page.innerHTML=h;document.querySelectorAll(".nav-link[data-view]").forEach(b=>b.classList.toggle("active",b.dataset.view===currentView));applySettings();if(currentView==="settings"){const s=settings();const values={"scale":s.scale,"nav-position":s.navPosition,"search-engine":s.searchEngine,"library-layout":s.libraryLayout,"library-layout-2":s.libraryLayout,"clock24":s.clock24,"clock-seconds":s.clockSeconds,"accent":s.accent,"compact":s.compact,"animations":s.animations,"motion":s.motion,"desc":s.showDescriptions,"confirm":s.confirm,"background":s.background,"corners":s.corners,"density":s.density,"hover-effects":s.hoverEffects,"page-transitions":s.pageTransitions,"show-status":s.showStatus};for(const [id,value] of Object.entries(values)){const el=$("#s-"+id);if(el){if(el.type==="checkbox")el.checked=!!value;else el.value=value}}const preview=$(".options-preview");if(preview)preview.style.setProperty("--preview-accent",s.accent);}if(currentView==="ai")setupAI();if(currentView==="search"){const form=$("#wiki-search-form");form?.addEventListener("submit",async e=>{e.preventDefault();await runWikiSearch($("#wiki-search-input").value)});const params=new URLSearchParams(location.search);const initial=params.get("q");if(initial){$("#wiki-search-input").value=initial;runWikiSearch(initial)}}if(currentView==="games"){const q=$("#game-search"),sort=$("#game-sort"),category=$("#game-category-filter");const filter=()=>{const term=q.value.toLowerCase(),cat=category.value;const found=games.filter(g=>(g.name+" "+g.description+" "+g.category).toLowerCase().includes(term)&&(!cat||g.category===cat));const ordered=sort.value==="recent"?found.filter(g=>recents().includes(g.id)).sort((x,y)=>recents().indexOf(x.id)-recents().indexOf(y.id)):sorted(found);$("#page .game-grid").outerHTML=grid(ordered).replace("game-grid","game-grid "+(settings().libraryLayout==="cards"?"cards-layout":"grid-layout"))};q.addEventListener("input",filter);category.addEventListener("change",filter);sort.addEventListener("change",filter)}}
function showView(v){currentView=v;shell.hidden=true;page.hidden=false;pageRender()}
function renderTabs(){runningTabs.innerHTML=sessions.map(s=>'<button class="nav-link running-game-tab '+(s.id===activeSessionId?'active':'')+'" data-session="'+esc(s.id)+'"><span>▶</span><span class="running-game-name">'+esc(s.game.name)+'</span><span class="running-game-close" data-close-session="'+esc(s.id)+'">×</span></button>').join("");}
function activateSession(id){const s=sessions.find(x=>x.id===id);if(!s)return;document.body.classList.add("game-active");activeSessionId=id;activeGame=s.game;frame=s.frame;sessions.forEach(item=>item.frame.hidden=item.id!==id);$("#player-title").textContent=s.game.name;renderTabs();currentView="game-player";page.hidden=true;shell.hidden=false;document.querySelectorAll(".nav-link[data-view]").forEach(x=>x.classList.remove("active"));}
function launch(g){if(settings().confirm&&!confirm("Open "+g.name+"?"))return;const id=(crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2));const f=document.createElement("iframe");f.allow="fullscreen; autoplay; gamepad";f.allowFullscreen=true;f.referrerPolicy="strict-origin-when-cross-origin";f.title=g.name;f.style.cssText="width:100%;height:100%;border:0;display:block;background:#000";if(g.html){f.setAttribute("sandbox","allow-scripts allow-forms allow-pointer-lock allow-downloads");f.srcdoc=g.html}else{if(g.isolated){f.setAttribute("sandbox","allow-scripts allow-forms allow-pointer-lock allow-downloads allow-same-origin");const token=crypto.randomUUID?crypto.randomUUID():Math.random().toString(36).slice(2);sessionStorage.setItem("sme-isolated-game:"+token,JSON.stringify({url:typeof g.isolated==="string"?safeSrc(g.isolated):g.src,createdAt:Date.now()}));f.src="/locked-quiz.html#"+encodeURIComponent(token)}else f.src=g.src;}f.hidden=true;frameStage.append(f);sessions.push({id,game:g,frame:f});shell.hidden=false;activateSession(id);const r=recents().filter(x=>x!==g.id);r.unshift(g.id);put("sunset_recent",r.slice(0,80));const st=stats();st.launches++;setStats(st);if(tick)clearInterval(tick);tick=setInterval(()=>{if(!activeGame)return;const v=stats();v.seconds++;if(v.seconds%5===0)setStats(v);$("#player-time").textContent=new Date(v.seconds*1000).toISOString().slice(11,19)},1000);toast("Opened "+g.name+" in a new tab");}
function closeSession(id){const i=sessions.findIndex(s=>s.id===id);if(i<0)return;const wasActive=id===activeSessionId;sessions[i].frame.src="about:blank";sessions[i].frame.remove();sessions.splice(i,1);if(!sessions.length){closePlayer();return}if(wasActive){const next=sessions[Math.min(i,sessions.length-1)];activateSession(next.id)}else renderTabs();}
function closePlayer(){document.body.classList.remove("game-active");sessions.forEach(s=>{s.frame.src="about:blank";s.frame.remove()});sessions=[];activeSessionId=null;frame=null;activeGame=null;shell.hidden=true;page.hidden=false;currentView="games";if(tick)clearInterval(tick);tick=null;renderTabs();pageRender();toast("All game tabs closed");}
function minimise(){document.body.classList.remove("game-active");shell.hidden=true;page.hidden=false;currentView="home";pageRender();}
function restore(){if(activeSessionId)activateSession(activeSessionId);}
function showModal(t,h,buttons){body.innerHTML='<h2 id="modal-title">'+esc(t)+'</h2>'+h;footer.innerHTML="";buttons.forEach(x=>{const b=document.createElement("button");b.className="button "+(x.primary?"primary":"secondary");b.textContent=x.label;b.onclick=x.run||closeModal;footer.append(b)});modal.hidden=false}
function closeModal(){modal.hidden=true}
async function load(){$("#catalogue-status").textContent="Connecting to game catalogue…";try{const response=await fetch(CATALOGUE,{cache:"no-store"});if(!response.ok)throw Error("Catalogue request failed: "+response.status);const data=await response.json();if(!Array.isArray(data))throw Error("Catalogue format was not recognised");games=data.map((g,i)=>({id:String(g.id??i),name:String(g.name||"Untitled game"),description:String(g.description||g.desc||"Open this game."),src:safeSrc(g.src||g.url),image:safeImage(g.image||g.icon),category:String(g.category||g.type||"Game"),isolated:g.isolated||false})).filter(g=>g.name&&g.src);$("#game-count").textContent=games.length;$("#catalogue-status").textContent=games.length+" games available";pageRender()}catch(error){games=[];$("#game-count").textContent="0";$("#catalogue-status").textContent="Catalogue unavailable";pageRender();console.error("Solaris catalogue error:",error);toast("Could not load the Snubby game catalogue. Check your connection and reload.")}}
const aiSession={history:[],activeChatId:null,attachments:[]};
function aiChats(){return get("sunset_ai_chats",[])}
function saveAIChat(){const chats=aiChats();let chat=chats.find(x=>x.id===aiSession.activeChatId);if(!chat){chat={id:aiSession.activeChatId||("chat-"+Date.now()),title:"New chat",messages:[],updated:Date.now()};aiSession.activeChatId=chat.id;chats.unshift(chat)}chat.messages=aiSession.history.slice(-200);chat.updated=Date.now();chats.sort((x,y)=>y.updated-x.updated);put("sunset_ai_chats",chats.slice(0,30))}
function setAIChatTitle(title){const words=String(title||"").replace(/[^a-zA-Z0-9\s'-]/g," ").trim().split(/\s+/).filter(Boolean).slice(0,3);if(!words.length)return;while(words.length<3)words.push(["Chat","Notes","Ideas"][words.length-1]);const chats=aiChats(),chat=chats.find(x=>x.id===aiSession.activeChatId);if(!chat)return;chat.title=words.join(" ");chat.updated=Date.now();put("sunset_ai_chats",chats);refreshAIChatPicker()}
function renderAIHistory(){const log=$("#ai-log");if(!log)return;log.innerHTML=aiSession.history.length?aiSession.history.map(m=>'<div class="ai-message '+m.role+'"><b>'+(m.role==="user"?"You":"Assistant")+'</b><div class="ai-richtext">'+formatAIText(m.content)+'</div></div>').join(""):'<p class="ai-empty">Your conversation will appear here. Start a new chat or send a message.</p>';log.scrollTop=log.scrollHeight}
function refreshAIChatPicker(){const list=$("#ai-chat-list");if(!list)return;const query=($("#ai-chat-search")?.value||"").toLowerCase();const chats=aiChats().filter(c=>(c.title||"New chat").toLowerCase().includes(query));list.innerHTML=chats.map(c=>'<div class="ai-chat-row"><button type="button" class="ai-chat-item '+(c.id===aiSession.activeChatId?"active":"")+'" data-ai-chat="'+esc(c.id)+'"><span>◌</span><b>'+esc(c.title||"New chat")+'</b></button><button type="button" class="ai-chat-action" data-ai-rename="'+esc(c.id)+'" title="Rename chat">✎</button><button type="button" class="ai-chat-action" data-ai-export="'+esc(c.id)+'" title="Export chat">↓</button><button type="button" class="ai-chat-action" data-ai-delete="'+esc(c.id)+'" title="Delete chat">×</button></div>').join("")||'<p class="ai-chat-empty">No matching chats.</p>';const title=$("#ai-current-title");if(title)title.textContent=aiChats().find(c=>c.id===aiSession.activeChatId)?.title||"New conversation"}
function loadAIChat(id){const chat=aiChats().find(x=>x.id===id);aiSession.activeChatId=chat?.id||null;aiSession.history=chat?.messages?.slice(-200)||[];renderAIHistory();refreshAIChatPicker()}
function newAIChat(){aiSession.activeChatId="chat-"+(crypto.randomUUID?crypto.randomUUID():Date.now());aiSession.history=[];aiSession.attachments=[];saveAIChat();renderAIHistory();refreshAIChatPicker();$("#ai-attachments").textContent="";$("#ai-prompt").focus()}

