 const ai=get("sunset_ai_settings",{provider:"openai",model:"gpt-4o-mini"}),provider=$("#ai-provider"),model=$("#ai-model"),key=$("#ai-key"),custom=$("#ai-custom-model"),customWrap=$("#ai-custom-wrap");
 const models={openai:["gpt-4o-mini","gpt-4.1-mini","gpt-4.1","gpt-4o","o4-mini","o3-mini"],gemini:["gemini-2.5-flash","gemini-2.5-pro","gemini-2.0-flash","gemini-2.0-flash-lite","gemini-1.5-pro"],nim:["nvidia/nemotron-3-ultra-550b-a55b","meta/llama-3.1-8b-instruct","meta/llama-3.3-70b-instruct","nvidia/llama-3.1-nemotron-70b-instruct","deepseek-ai/deepseek-r1","qwen/qwen2.5-coder-32b-instruct","mistralai/mistral-small-24b-instruct-2501"]};
