function formatAIText(value){
 let text=esc(String(value)).replace(/\r\n?/g,"\n"),blocks=[];
 text=text.replace(/\x60{3}([a-zA-Z0-9_+-]*)\n?([\s\S]*?)\x60{3}|'{3}([a-zA-Z0-9_+-]*)\n([\s\S]*?)'{3}/g,(_,la,ca,lb,cb)=>{const token="@@SUNSET_CODE_"+blocks.length+"@@";blocks.push('<pre class="ai-code"><span class="ai-code-lang">'+esc(la||lb||"code")+'</span><button type="button" class="ai-copy-code" title="Copy code">Copy</button><code>'+ (ca??cb??"") +'</code></pre>');return token;});
 const inline=v=>v.replace(/\*\*(.+?)\*\*/g,"<strong>$1</strong>").replace(/\*([^*]+)\*/g,"<em>$1</em>").replace(/\x60([^\x60]+)\x60/g,'<code class="ai-inline-code">$1</code>');
 const rows=text.split("\n"),out=[];let list="";
 const closeList=()=>{if(list){out.push("</"+list+">");list="";}};
 const cells=line=>line.trim().replace(/^\||\|$/g,"").split("|").map(x=>x.trim());
 for(let i=0;i<rows.length;i++){
  const line=rows[i],trim=line.trim();
  if(!trim){closeList();continue;}
  if(trim.includes("|")&&i+1<rows.length&&/^\s*\|?\s*:?-{3,}:?\s*(\|\s*:?-{3,}:?\s*)+\|?\s*$/.test(rows[i+1])){
   closeList();const head=cells(line),body=[];i+=2;while(i<rows.length&&rows[i].includes("|")&&rows[i].trim()){body.push(cells(rows[i]));i++;}i--;
   out.push("<div class=\"ai-table-wrap\"><table class=\"ai-table\"><thead><tr>"+head.map(c=>"<th>"+inline(c)+"</th>").join("")+"</tr></thead><tbody>"+body.map(r=>"<tr>"+head.map((_,n)=>"<td>"+inline(r[n]||"")+"</td>").join("")+"</tr>").join("")+"</tbody></table></div>");continue;
  }
  const heading=trim.match(/^(#{1,6})\s+(.+)$/);if(heading){closeList();const n=Math.min(heading[1].length,4);out.push("<h"+n+" class=\"ai-heading\">"+inline(heading[2])+"</h"+n+">");continue;}
  if(/^([-*_])\1\1+$/.test(trim)){closeList();out.push("<hr class=\"ai-divider\">");continue;}
  const ul=trim.match(/^[-*]\s+(.+)$/),ol=trim.match(/^\d+[.)]\s+(.+)$/);
  if(ul||ol){const type=ul?"ul":"ol";if(list!==type){closeList();list=type;out.push("<"+type+" class=\"ai-list\">");}out.push("<li>"+inline((ul||ol)[1])+"</li>");continue;}
  const quote=trim.match(/^&gt;\s?(.+)$/);if(quote){closeList();out.push("<blockquote class=\"ai-quote\">"+inline(quote[1])+"</blockquote>");continue;}
  closeList();if(trim.startsWith("@@SUNSET_CODE_"))out.push(trim);else out.push("<p>"+inline(line)+"</p>");
 }
 closeList();
 let html=out.join("");blocks.forEach((b,i)=>{html=html.replace("<p>@@SUNSET_CODE_"+i+"@@</p>",b).replace("@@SUNSET_CODE_"+i+"@@",b);});
 return html;
}async function typeAIAnswer(node,answer){const parts=answer.split(/(\u0060{3}[a-zA-Z0-9_+-]*\n?[\s\S]*?\u0060{3})/g);node.innerHTML="";for(const part of parts){if(!part)continue;if(part.startsWith("\u0060\u0060\u0060")){const box=document.createElement("div");box.innerHTML=formatAIText(part);node.append(box);continue}const span=document.createElement("span");span.style.whiteSpace="pre-wrap";node.append(span);for(let i=0;i<part.length;i+=3){span.textContent+=part.slice(i,i+3);if(i%30===0){const log=node.closest(".ai-log");if(log)log.scrollTop=log.scrollHeight;await new Promise(resolve=>setTimeout(resolve,7))}}}node.innerHTML=formatAIText(answer)}
