let feedbackConsole=[];
const consoleOriginal={log:console.log.bind(console),warn:console.warn.bind(console),error:console.error.bind(console)};
function feedbackValue(value){try{if(value instanceof Error)return value.stack||value.message;if(typeof value==="string")return value;if(value===null||typeof value!=="object")return String(value);return JSON.stringify(value)}catch{return String(value)}}
function recordFeedbackConsole(level,args){feedbackConsole.push(("["+level.toUpperCase()+"] "+args.map(feedbackValue).join(" ")).slice(0,1200));if(feedbackConsole.length>80)feedbackConsole.shift()}
["log","warn","error"].forEach(level=>{console[level]=(...args)=>{recordFeedbackConsole(level,args);consoleOriginal[level](...args)}});
window.addEventListener("error",event=>recordFeedbackConsole("error",[event.message||"Window error",event.filename||"",event.lineno?("line "+event.lineno):""]));
window.addEventListener("unhandledrejection",event=>recordFeedbackConsole("error",["Unhandled promise rejection",event.reason]));
async function readFeedbackImage(file){if(!["image/png","image/jpeg","image/webp"].includes(file.type))throw Error("Only PNG, JPG and WebP images are supported.");if(file.size>2*1024*1024)throw Error(file.name+" is larger than 2 MB.");return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve({name:file.name,type:file.type,data:String(reader.result).split(",")[1]});reader.onerror=()=>reject(Error("Could not read "+file.name));reader.readAsDataURL(file)})}
